  scheinen: "stark",
  wachsen: "stark",
  fliegen: "stark",
  fallen: "stark",
  liegen: "stark",
  stehen: "stark",
  machen: "schwach",
  arbeiten: "schwach",
  lernen: "schwach",
  spielen: "schwach",
  kaufen: "schwach",
  bezahlen: "schwach",
  verkaufen: "schwach",
